unsafe fn world_hash(fi: usize) -> u64 {
    let mut h = FNV0;
    for i in 0..NGO { h = img_hash(h, core::slice::from_raw_parts(addr_of!(OGO[i]) as *const u8, core::mem::size_of_val(&*addr_of!(OGO[i]))), D_HSD_GObj);  }
    for i in 0..NGO {
        match GVAR[fi] {
            0 => { h = img_hash(h, core::slice::from_raw_parts(addr_of!(OGP[i]) as *const u8, core::mem::size_of_val(&*addr_of!(OGP[i]))), D_Ground_0); h = bf_hash_Ground_0(h, addr_of!(OGP[i]) as *const Ground); }
            _ => unreachable!(),
        }
    }
    for i in 0..NJO { h = img_hash(h, core::slice::from_raw_parts(addr_of!(OJO[i]) as *const u8, core::mem::size_of_val(&*addr_of!(OJO[i]))), D_HSD_JObj);  }
    h = img_hash(h, core::slice::from_raw_parts(addr_of!(G_stage_info) as *const u8, 3256), D_StageInfo); h = bf_hash_StageInfo(h, addr_of!(G_stage_info) as *const StageInfo);
    h = img_hash(h, core::slice::from_raw_parts(addr_of!(OP_HSD_GObjProc[0]) as *const u8, core::mem::size_of_val(&*addr_of!(OP_HSD_GObjProc[0]))), D_HSD_GObjProc); h = bf_hash_HSD_GObjProc(h, addr_of!(OP_HSD_GObjProc[0]) as *const HSD_GObjProc); h = img_hash(h, core::slice::from_raw_parts(addr_of!(OP_HSD_GObjProc[1]) as *const u8, core::mem::size_of_val(&*addr_of!(OP_HSD_GObjProc[1]))), D_HSD_GObjProc); h = bf_hash_HSD_GObjProc(h, addr_of!(OP_HSD_GObjProc[1]) as *const HSD_GObjProc);
    h = img_hash(h, core::slice::from_raw_parts(addr_of!(OP_HSD_Generator[0]) as *const u8, core::mem::size_of_val(&*addr_of!(OP_HSD_Generator[0]))), D_HSD_Generator);  h = img_hash(h, core::slice::from_raw_parts(addr_of!(OP_HSD_Generator[1]) as *const u8, core::mem::size_of_val(&*addr_of!(OP_HSD_Generator[1]))), D_HSD_Generator); 
    h = img_hash(h, core::slice::from_raw_parts(addr_of!(OP_HSD_psAppSRT[0]) as *const u8, core::mem::size_of_val(&*addr_of!(OP_HSD_psAppSRT[0]))), D_HSD_psAppSRT);  h = img_hash(h, core::slice::from_raw_parts(addr_of!(OP_HSD_psAppSRT[1]) as *const u8, core::mem::size_of_val(&*addr_of!(OP_HSD_psAppSRT[1]))), D_HSD_psAppSRT); 
    h = img_hash(h, core::slice::from_raw_parts(addr_of!(OP_Fighter[0]) as *const u8, core::mem::size_of_val(&*addr_of!(OP_Fighter[0]))), D_Fighter);  h = img_hash(h, core::slice::from_raw_parts(addr_of!(OP_Fighter[1]) as *const u8, core::mem::size_of_val(&*addr_of!(OP_Fighter[1]))), D_Fighter); 
    h = img_hash(h, core::slice::from_raw_parts(addr_of!(OP_Item[0]) as *const u8, core::mem::size_of_val(&*addr_of!(OP_Item[0]))), D_Item);  h = img_hash(h, core::slice::from_raw_parts(addr_of!(OP_Item[1]) as *const u8, core::mem::size_of_val(&*addr_of!(OP_Item[1]))), D_Item); 
    h = img_hash(h, core::slice::from_raw_parts(addr_of!(OP_DynamicModelDesc[0]) as *const u8, core::mem::size_of_val(&*addr_of!(OP_DynamicModelDesc[0]))), D_DynamicModelDesc);  h = img_hash(h, core::slice::from_raw_parts(addr_of!(OP_DynamicModelDesc[1]) as *const u8, core::mem::size_of_val(&*addr_of!(OP_DynamicModelDesc[1]))), D_DynamicModelDesc); 
    h = img_hash(h, core::slice::from_raw_parts(addr_of!(OP_DynamicsDesc[0]) as *const u8, core::mem::size_of_val(&*addr_of!(OP_DynamicsDesc[0]))), D_DynamicsDesc);  h = img_hash(h, core::slice::from_raw_parts(addr_of!(OP_DynamicsDesc[1]) as *const u8, core::mem::size_of_val(&*addr_of!(OP_DynamicsDesc[1]))), D_DynamicsDesc); 
    h = img_hash(h, core::slice::from_raw_parts(addr_of!(OP_HSD_AObj[0]) as *const u8, core::mem::size_of_val(&*addr_of!(OP_HSD_AObj[0]))), D_HSD_AObj);  h = img_hash(h, core::slice::from_raw_parts(addr_of!(OP_HSD_AObj[1]) as *const u8, core::mem::size_of_val(&*addr_of!(OP_HSD_AObj[1]))), D_HSD_AObj); 
    h = img_hash(h, core::slice::from_raw_parts(addr_of!(t::grLib_8049EF58) as *const u8, core::mem::size_of_val(&*addr_of!(t::grLib_8049EF58))), D_st0);
    h = img_hash(h, core::slice::from_raw_parts(addr_of!(t::ext::hsd_804D78FC) as *const u8, core::mem::size_of_val(&*addr_of!(t::ext::hsd_804D78FC))), D_st1);
    h = img_hash(h, core::slice::from_raw_parts(addr_of!(t::ext::HSD_GObjPLinkHead) as *const u8, core::mem::size_of_val(&*addr_of!(t::ext::HSD_GObjPLinkHead))), D_st2);
    h = img_hash(h, core::slice::from_raw_parts(addr_of!(t::ext::HSD_GObj_JObjKind) as *const u8, core::mem::size_of_val(&*addr_of!(t::ext::HSD_GObj_JObjKind))), D_st3);
    h = img_hash(h, core::slice::from_raw_parts(addr_of!(PL) as *const u8, core::mem::size_of_val(&*addr_of!(PL))), D_st4);
    h = img_hash(h, core::slice::from_raw_parts(addr_of!(QA) as *const u8, core::mem::size_of_val(&*addr_of!(QA))), D_st5);
    h = word_hash(h, core::slice::from_raw_parts(addr_of!(OSCR) as *const u8, core::mem::size_of_val(&*addr_of!(OSCR))));
    h
}
#[test]
fn state_matches_c() {
    unsafe {
        let want = include_str!("data/gro_grlib.txt");
        let mut lines = want.lines();
        let verbose = std::env::var("ORACLE_VERBOSE").ok();
        let hdr: std::vec::Vec<usize> = lines.next().unwrap().split_whitespace().skip(1).map(|s| s.parse().unwrap()).collect();
        let sizes: std::vec::Vec<usize> = std::vec![core::mem::size_of::<Ground>(), core::mem::size_of::<HSD_GObj>(), core::mem::size_of::<HSD_JObj>(), core::mem::size_of::<StageInfo>(), core::mem::size_of_val(&*addr_of!(t::grLib_8049EF58)), core::mem::size_of_val(&*addr_of!(t::ext::hsd_804D78FC)), core::mem::size_of_val(&*addr_of!(t::ext::HSD_GObjPLinkHead)), core::mem::size_of_val(&*addr_of!(t::ext::HSD_GObj_JObjKind)), core::mem::size_of_val(&*addr_of!(PL)), core::mem::size_of_val(&*addr_of!(QA))];
        assert_eq!(hdr, sizes, "struct sizes (C native layout vs the Rust port)");
        install_hooks();
        world_reg();
        world_reg_fns();
        let mut bad = std::vec::Vec::new();
        for (fi, fnn) in FNS.iter().enumerate() {
            let mut agg = FNV0;
            let vb = verbose.as_deref() == Some(fnn.name);
            if verbose.is_some() && !vb {
                continue;
            }
            for k in 0..fnn.n {
                let mut h = FNV0;
                RS = 0x9E37_79B9u32 ^ ((fi as u32).wrapping_mul(7919).wrapping_add(k.wrapping_mul(104729)).wrapping_add(1));
                world_fill(fi);
                let mut a = core::mem::zeroed::<Args>();
                for i in 0..4 { a.i[i] = rnd() % 4; }
                for i in 0..2 { a.f[i] = rf(); }
                for i in 0..2 { a.v3[i].x = rf(); a.v3[i].y = rf(); a.v3[i].z = rf(); }
                for i in 0..2 { a.v2[i].x = rf(); a.v2[i].y = rf(); }
                for i in 0..2 { a.pf[i] = rf(); }
                for i in 0..2 { a.pi[i] = (rnd() % 8) as i32; }
                case_pre(fi, &mut a);
                LG.clear();
                let (rv, _rb) = call_fn(fi, &mut a);
                let ho = fnv(FNV0, LG.as_bytes());
                let hw = world_hash(fi);
                for x in [ho, rv, hw] {
                    h = fnv(h, &x.to_le_bytes());
                }
                h = fnv(h, &canon_f32_bytes(&[a.v3[0].x, a.v3[0].y, a.v3[0].z, a.v3[1].x, a.v3[1].y, a.v3[1].z]));
                h = fnv(h, &canon_f32_bytes(&[a.v2[0].x, a.v2[0].y, a.v2[1].x, a.v2[1].y]));
                h = fnv(h, &canon_f32_bytes(&a.pf));
                h = fnv(h, bytes(&a.pi));
                if vb {
                    println!("{} {:016x} ret={:x} W={:016x} L={:016x}\n  {}", k, h, rv, hw, ho, LG);
                }
                agg = fnv(agg, &h.to_le_bytes());
            }
            if verbose.is_some() {
                continue;
            }
            let line = lines.next().expect("data file shorter than the function table");
            let (cname, chash) = line.split_once(' ').unwrap();
            assert_eq!(cname, fnn.name, "data file and function table out of step");
            if u64::from_str_radix(chash, 16).unwrap() != agg {
                bad.push(fnn.name);
            }
        }
        assert!(bad.is_empty(), "{} of {} functions differ from the C: {:?}", bad.len(), FNS.len(), bad);
    }
}
